// ─── File: ReplayDemo.java ───
// Prevents replay: signature + freshness window + nonce dedupe (Redis SET NX EX).
package com.bank.gateway.demo;

import java.math.BigDecimal;
import java.util.UUID;
import java.util.logging.*;

public class ReplayDemo {
    private static final Logger log = Logger.getLogger("ReplayGuard");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new RpLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ReplayStore sharedStore = new ReplayStore();          // simulates shared Redis
        TransferGateway replicaA = new TransferGateway(new ReplayGuard(sharedStore, 300));
        TransferGateway replicaB = new TransferGateway(new ReplayGuard(sharedStore, 300)); // same store

        // A genuine captured request the attacker will replay.
        long now = System.currentTimeMillis();
        String nonce = UUID.randomUUID().toString();
        SignedRequest genuine = new SignedRequest("rajesh", new BigDecimal("50000"), nonce, now, true);

        log.info("=== Genuine transfer (first time) ===");
        replicaA.transfer(genuine);

        log.info("=== Attacker replays same request 4x (to replica A) ===");
        for (int i = 0; i < 4; i++) replicaA.transfer(genuine);

        log.info("=== Attacker replays to a DIFFERENT replica (shared Redis catches it) ===");
        replicaB.transfer(genuine);

        log.info("=== Stale timestamp (outside freshness window) ===");
        SignedRequest stale = new SignedRequest("rajesh", new BigDecimal("50000"),
                UUID.randomUUID().toString(), now - 600_000, true); // 10 min old
        replicaA.transfer(stale);

        log.info("=== Tampered (bad signature) ===");
        SignedRequest tampered = new SignedRequest("rajesh", new BigDecimal("50000"),
                UUID.randomUUID().toString(), System.currentTimeMillis(), false);
        replicaA.transfer(tampered);
    }
}

