class SignedRequest {
    final String user; final BigDecimal amount; final String nonce;
    final long timestampMs; final boolean signatureValid;
    SignedRequest(String user, BigDecimal amount, String nonce, long timestampMs, boolean signatureValid) {
        this.user = user; this.amount = amount; this.nonce = nonce;
        this.timestampMs = timestampMs; this.signatureValid = signatureValid;
    }
}

// ─── Would be in replay/ReplayStore.java ───
// Models Redis SET key value NX EX <ttl> with automatic expiry.
class ReplayStore {
    private final java.util.Map<String, Long> seen = new java.util.concurrent.ConcurrentHashMap<>();
    // Atomic set-if-absent; returns true only if the nonce was NOT seen before.
    boolean setIfAbsent(String nonce, long ttlMs) {
        long expiresAt = System.currentTimeMillis() + ttlMs;
        Long prev = seen.putIfAbsent(nonce, expiresAt); // atomic NX
        if (prev == null) return true;                  // brand new nonce
        if (System.currentTimeMillis() > prev) {        // expired → treat as new, refresh
            seen.put(nonce, expiresAt);
            return true;
        }
        return false;                                   // still-valid duplicate → replay
    }
}

// ─── Would be in replay/ReplayGuard.java ───
class ReplayGuard {
    private static final Logger log = Logger.getLogger("ReplayGuard");
    private final ReplayStore store; private final long windowSeconds;
    ReplayGuard(ReplayStore store, long windowSeconds) { this.store = store; this.windowSeconds = windowSeconds; }

    enum Result { ALLOW, BAD_SIGNATURE, STALE, REPLAY }

    Result check(SignedRequest req) {
        // 1) signature: tampering with nonce/timestamp invalidates the request.
        if (!req.signatureValid) return Result.BAD_SIGNATURE;
        // 2) freshness: reject anything outside the window (also bounds nonce memory).
        long ageMs = System.currentTimeMillis() - req.timestampMs;
        if (ageMs > windowSeconds * 1000 || ageMs < -30_000) return Result.STALE;
        // 3) dedupe: atomic set-if-absent with TTL == window.
        boolean fresh = store.setIfAbsent(req.nonce, windowSeconds * 1000);
        return fresh ? Result.ALLOW : Result.REPLAY;
    }
}

// ─── Would be in core/TransferGateway.java ───
class TransferGateway {
    private static final Logger log = Logger.getLogger("ReplayGuard");
    private final ReplayGuard guard;
    TransferGateway(ReplayGuard guard) { this.guard = guard; }
    void transfer(SignedRequest req) {
        ReplayGuard.Result r = guard.check(req);
        switch (r) {
            case ALLOW:
                log.info(() -> "EXECUTE transfer user=" + req.user + " amount=" + req.amount
                        + " nonce=" + req.nonce.substring(0, 8));
                break;
            case BAD_SIGNATURE: log.severe("REJECT: bad signature (tampered)"); break;
            case STALE:         log.warning("REJECT: stale timestamp (outside freshness window)"); break;
            case REPLAY:        log.severe(() -> "REJECT: replay detected nonce=" + req.nonce.substring(0, 8)); break;
        }
    }
}

